"""Replay double of `runlog.Run`: a run folder's recorded record, episodes, evals and checkpoints."""

from dataclasses import dataclass
from typing import Any

from rllab.core import EpisodeResult
from rllab.runlog import Checkpoint, EvalPoint, RunRecord


@dataclass(frozen=True)
class ReplayRun:
    record: RunRecord
    recorded_episodes: tuple[EpisodeResult, ...]
    recorded_evals: tuple[EvalPoint, ...]
    recorded_checkpoints: tuple[Checkpoint, ...]

    def episodes(self) -> list[EpisodeResult]:
        return list(self.recorded_episodes)

    def evals(self) -> list[EvalPoint]:
        return list(self.recorded_evals)

    def checkpoints(self) -> list[Checkpoint]:
        return list(self.recorded_checkpoints)


def build(kit: Any, recording: dict[str, Any]) -> ReplayRun:
    return ReplayRun(
        kit.decode(RunRecord, recording["record"]),
        kit.decode(tuple[EpisodeResult, ...], recording["episodes"]),
        kit.decode(tuple[EvalPoint, ...], recording["evals"]),
        kit.decode(tuple[Checkpoint, ...], recording["checkpoints"]),
    )
"""Fake of `charts.learning_curve`: writes a placeholder PNG at `out` and names its runs."""

from collections.abc import Callable, Sequence
from pathlib import Path
from typing import Any

import numpy as np
from matplotlib import image

from rllab.core import BaselineMeans, Output
from rllab.runlog import Run


def build(kit: Any) -> Callable[..., Output]:
    def learning_curve(
        runs: Sequence[Run], baselines: BaselineMeans, out: Path, *, measure: str | None = None
    ) -> Output:
        out.parent.mkdir(parents=True, exist_ok=True)
        image.imsave(out, np.ones((4, 4, 3)))
        return Output(out, "chart", tuple(run.record.config.name for run in runs))

    return learning_curve
